using HealthTracker.Api.Models;using Microsoft.EntityFrameworkCore;namespace HealthTracker.Api.Data;public class AppDbContext:DbContext{public AppDbContext(DbContextOptions<AppDbContext> options):base(options){}public DbSet<AppUser> Users=>Set<AppUser>();public DbSet<Patient> Patients=>Set<Patient>();public DbSet<Medicine> Medicines=>Set<Medicine>();public DbSet<DoseEvent> DoseEvents=>Set<DoseEvent>();protected override void OnModelCreating(ModelBuilder b){b.Entity<AppUser>().HasIndex(x=>x.Email).IsUnique();b.Entity<Patient>().HasIndex(x=>x.UserId);b.Entity<Medicine>().HasIndex(x=>x.PatientId);}}